@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap');
:root{--ink:#f3ecdb;--muted:#b3b09e;--gold:#e4bd70;--gold2:#f0d99d;--panel:rgba(20,25,20,.94);--edge:rgba(233,210,157,.24);--red:#cf5d4c;--green:#97bd75}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#111710;color:var(--ink);font-family:'DM Sans',sans-serif;overflow:hidden;touch-action:none}button{font:inherit;color:inherit;cursor:pointer}#game{position:relative;width:100%;height:100%;overflow:hidden;background:#354d3a;isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 46%,transparent 42%,rgba(5,9,7,.35) 100%),linear-gradient(180deg,rgba(8,12,10,.5),transparent 25%,transparent 60%,rgba(8,12,10,.35)}.topbar{position:absolute;top:0;left:0;right:0;height:83px;padding:14px 28px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(12,17,14,.86),rgba(12,17,14,.28));border-bottom:1px solid rgba(255,255,255,.07)}.brand{border:0;background:none;display:flex;align-items:center;gap:11px;text-align:left;padding:0}.brand-mark{width:38px;height:38px;border:1px solid var(--gold);color:var(--gold);display:grid;place-items:center;transform:rotate(45deg);font-size:20px}.brand b,.brand small{display:block;letter-spacing:.14em}.brand b{font-size:12px;color:#f5e7c7}.brand small{font-size:8px;color:#aaa894;margin-top:3px;letter-spacing:.18em}.zone-title{position:absolute;left:50%;transform:translateX(-50%);text-align:center;min-width:260px}.zone-title span,.zone-title b,.zone-title small{display:block}.zone-title span{font-size:9px;letter-spacing:.2em;color:var(--gold);font-weight:700}.zone-title b{font-family:'Playfair Display',serif;font-size:19px;font-weight:600;margin:2px 0}.zone-title small{font-size:10px;color:#c5c1ad}.top-actions{display:flex;gap:8px}.icon-btn{width:38px;height:38px;background:rgba(16,23,18,.64);border:1px solid rgba(228,189,112,.3);border-radius:50%;font-size:19px;