gold);font-size:20px}.toast{position:absolute;left:50%;top:20%;transform:translate(-50%,-10px);opacity:0;padding:10px 18px;background:rgba(16,22,17,.91);border:1px solid var(--edge);color:var(--gold2);font-size:12px;letter-spacing:.04em;transition:.25s;pointer-events:none;z-index:5}.toast.show{opacity:1;transform:translate(-50%,0)}.interact-hint{position:absolute;left:50%;bottom:21%;transform:translateX(-50%);opacity:0;padding:7px 12px;background:rgba(17,22,17,.86);border:1px solid var(--edge);border-radius:3px;color:var(--gold);font-size:13px;transition:.15s}.interact-hint.show{opacity:1}.interact-hint span{color:#eee7d7;font-size:11px;margin:0 8px}kbd{font-size:9px;border:1px solid #777;padding:1px 5px;border-radius:2px;color:#ddd}.combat-feed{position:absolute;right:28px;top:202px;text-align:right;font-size:11px;line-height:1.75;color:#f2d994;text-shadow:0 1px 4px #000;pointer-events:none}.mobile-controls{display:none}.desktop-help{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);font-size:9px;color:rgba(241,234,217,.6);letter-spacing:.04em;white-space:nowrap}.desktop-help i{color:var(--gold);font-style:normal;margin:0 7px}.panel-shade{position:absolute;inset:0;background:rgba(4,7,5,.66);backdrop-filter:blur(5px);display:none;align-items:center;justify-content:center;z-index:10;padding:18px}.panel-shade.open{display:flex}.panel{position:relative;width:min(670px,100%);max-height:min(82vh,720px);overflow:auto;background:linear-gradient(145deg,#202a21,#141b16 68%);border:1px solid rgba(228,189,112,.38);box-shadow:0 24px 80px #000b;padding:27px 30px 28px}.panel:before{content:'';position:absolute;inset:6px;border:1px solid rgba(228,189,112,.1);pointer-events:none}.close{position:absolute;right:18px;top:14px;border:0;background:none;font-size:25px;color:#c7b98f;z-index:1}.panel h2{font:600 27px 'Playfair Display',serif;margin:3px 0;color:#f3e7cc}.eyebrow{font-size:9px;letter-spacing:.2em;color:var(--gold);font-weight:700}.panel p{font-size:12px;color: