ackground:#160f10d9}.death-mark{font-size:43px;color:#bd6255}.death-card>small{display:block;margin-top:10px;color:#d78c75;font-size:9px;letter-spacing:.2em}.death-card h2{font:600 30px 'Playfair Display',serif;margin:9px 0}.death-card p{color:#bbb0a6;font-size:12px;line-height:1.6}.death-card button{margin-top:12px;width:100%;padding:13px;background:#b89052;border:0;color:#211b13;font-size:10px;font-weight:700;letter-spacing:.12em}.death-card button span{float:right}
@media(max-width:700px){.topbar{height:66px;padding:10px 13px}.brand-mark{width:30px;height:30px;font-size:16px}.brand{gap:8px}.brand b{font-size:10px}.brand small{font-size:7px}.zone-title{top:12px;min-width:145px}.zone-title span{font-size:7px}.zone-title b{font-size:14px}.zone-title small{font-size:8px}.top-actions{gap:5px}.icon-btn{width:31px;height:31px;font-size:15px}.hero-hud{left:10px;top:74px;width:218px;padding:7px}.portrait{width:33px;height:38px;font-size:18px}.hero-line b{font-size:9px}.hero-line>span{font-size:7px}.objective{top:74px;right:10px;min-width:0;width:calc(100% - 242px);max-width:185px;padding:7px 8px;gap:6px}.quest-icon{font-size:14px}.objective small{font-size:6px;letter-spacing:.09em}.objective b{font-size:8px;line-height:1.25}.objective button{display:none}.combat-feed{top:auto;bottom:32%;right:12px;font-size:9px}.interact-hint{bottom:34%;font-size:11px}.desktop-help{display:none}.mobile-controls{display:block;position:absolute;inset:0;pointer-events:none}.joystick{position:absolute;bottom:max(27px,env(safe-area-inset-bottom));left:24px;width:132px;height:132px;pointer-events:auto;touch-action:none}.stick-ring{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(230,218,185,.38);background:rgba(19,26,21,.23);box-shadow:inset 0 0 25px #0003}.stick-knob{position:absolute;width:52px;height:52px;left:40px;top:40px;border-radius:50%;background:rgba(217,195,146,.37);border:1px solid rgba(243,225,182,.68);box-shadow:0 2px 12px #0006}.control-right{position:absolute;right:14px;bottom:max(22px,env(safe-area-inset-bottom));width:168px;height:164px;pointer-events:auto}.control-right button,.gather{position:absolute;border-radius:50%;display:grid;place-items:center;touch-action:none}.skill{width:44px;height:44px;border:1px solid rgba(234,208,147,.6);background:rgba(30,38,30,.8);color:#e8ce8e}.skill span{font-size:18px}.skill small{position:absolute;top:2px;right:5px;font-size:8px;color:#b9b19c}.skill#skill1{left:8px;top:10px}.skill#skil