const recipes=[{name:'Espada de cobre',type:'Herrería',need:{Madera:3,Cobre:5},effect:'Ataque +8',gain:'weapon'},{name:'Armadura de cuero',type:'Peletería',need:{Pieles:4,Lino:3},effect:'Vida máxima +25',gain:'armor'},{name:'Poción de vida',type:'Alquimia',need:{Hierbas:2,Setas:1},effect:'Recupera 45 de vida',gain:'potion'},{name:'Ración de viaje',type:'Cocina',need:{Pescado:1,Hierbas:1},effect:'Vida +20 · curación prolongada',gain:'food'},{name:'Encantar arma',type:'Encantamiento',need:{Polvo_arcano:2,Cobre:2},effect:'Daño +20% (durante la expedición)',gain:'rune'}];
