function save(){try{localStorage.setItem('wildfrontier-save',JSON.stringify(S))}catch{}}
function toast(text){let el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2100)}
function feed(text){let el=$('#combatFeed');el.innerHTML=`<div>${text}</div>`+el.innerHTML;el.innerHTML=el.innerHTML.split('</div>').slice(0,4).join('</div>');clearTimeout(feedTimer);feedTimer=setTimeout(()=>el.innerHTML='',3000)}
function mapMinLevel(m){return [1,16,31,46,56][Math.floor(m.tier)-1]}
function biome(){return palettes[S.map]}
function seed(n){let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
function makeWorld(){enemies=[];nodes=[];decor=[];let m=maps[S.map];for(let i=0;i<110;i++){let x=seed(i+100+S.map*333)*W,y=seed(i+600+S.map*999)*H;decor.push({x,y,t:seed(i+31)>0.62?'tree':seed(i+15)>0.45?'grass':'stone',r:15+seed(i+70)*28,v:seed(i+52)})}for(let i=0;i<34;i++){nodes.push({x:rand(100,W-100),y:rand(100,H-100),type:resourceType(m,i),ready:true,r:17+rand(0,5)})}for(let i=0;i<7;i++)spawnEnemy(true);}
function resourceType(m,i){let base=m.tier===1?['Madera','Cobre','Hierbas','Lino','Pescado']:m.tier===2?['Roble','Mineral','Hierbas','Raíz','Polvo_arcano']:m.tier===3?['Mineral','Pieles','Setas','Hierbas','Lino']:m.tier===4?['Polvo_arcano','Mineral','Hierbas','Pieles','Roble']:['Polvo_arcano','Mineral','Raíz','Setas','Pieles'];return base[i%base.length]}
function spawnEnemy(initial=false){let a=rand(0,Math.PI*2),r=initial?rand(230,520):rand(520,720);let m=maps[S.map],idx=Math.floor(rand(0,m.enemies.length)),boss=S.map===14&&S.level>=56&&Math.random()<.14;let rare=Math.random()<.12;let enemy={x:clamp(S.x+Math.cos(a)*r,40,W-40),y:clamp(S.y+Math.sin(a)*r,40,H-40),name:boss?'Avatar de la Niebla':m.enemies[idx],hp:(boss?390:40+S.level*3+maps[S.map].tier*8),maxHp:boss?390:40+S.level*3+maps[S.map].tier*8,damage:(boss?22:5+maps[S.map].tier*3),speed:boss?38:rand(28,48)+maps[S.map].tier*3,r:boss?28:rare?21:17,rare,boss,hit:0,attack:rand(.3,1.8)};enemies.push(enemy)}
function resize(){let d=devicePixelRatio||1;screenW=innerWidth;screenH=innerHeight;canvas.width=Math.floor(screenW*d);canvas.height=Math.floor(screenH*d);ctx.setTransform(d,0,0,d,0,0)}addEventListener('resize',resize);resize();makeWorld();
function draw(){let now=performance.now(),dt=Math.min(.05,(now-last)/1000);last=now;if(!S.dead)update(dt);render();requestAnimationFrame(draw)}
function update(dt){S.day+=dt;night=(Math.sin(S.day*.035-Math.PI/2)+1)/2;attackCd=Math.max(0,attackCd-dt);skillCd=skillCd.map(c=>Math.max(0,c-dt));dodgeCd=Math.max(0,dodgeCd-dt);invuln=Math.max(0,invuln-dt);S.stam=Math.min(S.maxStam,S.stam+dt*13);S.hp=Math.min(S.maxHp,S.hp+dt*(S.food?1.2:.17));if(S.food)S.food=Math.max(0,S.food-dt);let mvx=move.x+(keys.KeyA||keys.ArrowLeft?-1:0)+(keys.KeyD||keys.ArrowRight?1:0),mvy=move.y+(keys.KeyW||keys.ArrowUp?-1:0)+(keys.KeyS||keys.ArrowDown?1:0),len=Math.hypot(mvx,mvy);if(len>1){mvx/=len;mvy/=len}let speed=155*(S.stam<8?.72:1);S.x=clamp(S.x+mvx*speed*dt,35,W-35);S.y=clamp(S.y+mvy*speed*dt,35,H-35);if(len>.1)S.stam=Math.max(0,S.stam-dt*3);
for(let e of enemies){let d=dist(e,S);e.attack-=dt;e.hit=Math.max(0,e.hit-dt);if(d<430){let dx=(S.x-e.x)/Math.max(d,1),dy=(S.y-e.y)/Math.max(d,1);if(d>e.r+25){e.x+=dx*e.speed*dt;e.y+=dy*e.speed*dt}else if(e.attack<=0&&invuln<=0){e.attack=e.boss?1.15:1.55;S.hp-=e.damage;invuln=.45;feed(`−${e.damage} vida`);if(S.hp<=0){die();break}}}}
if(enemies.length<7&&Math.random()<dt*.55)spawnEnemy();if(Math.random()<dt*.16){let ready=nodes.filter(n=>n.ready);if(ready.length<16){nodes.push({x:rand(80,W-80),y:rand(80,H-80),type:resourceType(maps[S.map],Math.floor(rand(0,7))),ready:true,r:19})}}
interactObj=[...nodes.filter(n=>n.ready),...(S.corpse?[S.corpse]:[])].filter(o=>dist(o,S)<76).sort((a,b)=>dist(a,S)-dist(b,S))[0]||null;$('#interactHint').classList.toggle('show',!!interactObj);$('#gatherBtn').classList.toggle('ready',!!interactObj);if(flashTimer>0){flashTimer-=dt;if(flashTimer<=0)$('#levelFlash').classList.remove('show')}updateHUD();
}
function updateHUD(){let m=maps[S.map],act=S.level<16?'ACTO I · TIER 1':S.level<31?'ACTO II · TIERRAS INTERIORES':S.level<46?'ACTO III · EXTREMOS ELEMENTALES':'ACTO IV · EL ABISMO';$('#actLabel').textContent=act;$('#zoneName').textContent=m.name;$('#weather').textContent=`${m.hazard} · ${night>.55?'Noche de Niebla':'Luz de día'}`;$('#levelText').textContent=`NV. ${S.level} · ${S.sub||S.primary||'ALDEANO'}`;$('#goldText').textContent=S.gold;$('#hpBar').style.width=`${100*S.hp/S.maxHp}%`;$('#hpText').textContent=`${Math.ceil(S.hp)} / ${S.maxHp}`;$('#xpBar').style.width=`${100*S.xp/xpNeed()}%`;$('#xpText').textContent=`${S.xp} / ${xpNeed()} XP`;$('#stamBar').style.width=`${100*S.stam/S.maxStam}%`;$('#questText').textContent=S.map===14&&S.kills>=35?'Derrota al Avatar de la Niebla.':S.level<15?'Sobrevive. Reúne recursos y encuentra el camino.':S.level<30?'Prepara equipo y avanza hacia las Tierras Interiores.':'La Niebla Cenicienta se extiende. Sigue la señal.'}
function xpNeed(){return 80+S.level*48}
function awardXP(amount){S.xp+=amount;while(S.xp>=xpNeed()&&S.level<60){S.xp-=xpNeed();S.level++;S.maxHp+=5;S.hp=Math.min(S.maxHp,S.hp+22);S.maxStam+=2;$('#levelFlashText').textContent=`NV. ${S.level}`;$('#levelFlash').classList.add('show');flashTimer=2.2;toast(`Nivel ${S.level} alcanzado`);if(S.level===15)chooseClass(false);if(S.level===30)chooseClass(true)}save()}
function attack(){if(attackCd>0||S.dead)return;attackCd=.46;let target=enemies.filter(e=>dist(e,S)<155).sort((a,b)=>dist(a,S)-dist(b,S))[0];if(!target){toast('Acércate a una criatura');return}hitEnemy(target,18+S.weapon*8+(S.primary==='Guerrero'?6:0),false)}
function hitEnemy(e,dmg,skill){e.hp-=dmg;e.hit=.12;for(let i=0;i<5;i++)particles.push({x:e.x,y:e.y,vx:rand(-45,45),vy:rand(-70,10),life:.4,color:e.boss?'#cf79ac':skill?'#e1ca7e':'#f1e4c5'});feed(`${skill?'✦ ':''}${Math.ceil(dmg)} daño`);if(e.hp<=0){enemies.splice(enemies.indexOf(e),1);S.kills++;sessionKills++;let gain=(e.boss?360:18+maps[S.map].tier*9)*(e.rare?2:1);awardXP(gain);let coin=e.boss?75:Math.floor(rand(2,7)+maps[S.map].tier);S.gold+=coin;if(Math.random()<.7){let r=resourceType(maps[S.map],Math.floor(rand(0,5)));addItem(r,e.boss?4:1+Math.floor(Math.random()*2))}if(e.boss){S.kills+=10;toast('¡El Avatar de la Niebla ha caído! Botín legendario obtenido.');S.inventory['Polvo_arcano']+=5}else feed(`+${gain} XP  ·  +${coin} ◈`);if(Math.random()<.16){S.potions++;toast('Botín: Poción de vida')}save()}}
function useSkill(index){if(S.dead||skillCd[index]>0)return;skillCd[index]=index===0?8:12;let target=enemies.filter(e=>dist(e,S)<245).sort((a,b)=>dist(a,S)-dist(b,S))[0];if(index===0){if(target){let d=55+(S.level*2)+(S.primary==='Mago'?18:0);for(let e of enemies.filter(e=>dist(e,target)<120))hitEnemy(e,d,true)}else{S.hp=Math.min(S.maxHp,S.hp+16);toast('Aliento arcano · +16 vida')}}else{S.hp=Math.min(S.maxHp,S.hp+S.maxHp*.2);S.invuln=0;invuln=1.1;S.stam=Math.min(S.maxStam,S.stam+35);toast('Baluarte · salud restaurada')}}
function dodge(){if(dodgeCd>0||S.stam<22||S.dead)return;dodgeCd=1.1;S.stam-=22;invuln=.55;let dx=move.x,dy=move.y;if(!dx&&!dy){dx=keys.KeyA?-1:keys.KeyD?1:0;dy=keys.KeyW?-1:keys.KeyS?1:0}if(!dx&&!dy)dy=-1;let l=Math.hypot(dx,dy)||1;S.x=clamp(S.x+dx/l*115,35,W-35);S.y=clamp(S.y+dy/l*115,35,H-35);for(let i=0;i<8;i++)particles.push({x:S.x,y:S.y,vx:rand(-60,60),vy:rand(-60,60),life:.3,color:'#e2cc95'})}
function addItem(type,n){if(!(type in S.inventory))S.inventory[type]=0;S.inventory[type]+=n}
function interact(){if(interactObj){if(interactObj===S.corpse){for(let [k,v] of Object.entries(S.corpse.items))addItem(k,v);S.corpse=null;toast('Has recuperado tu mochila');save();return}let item=interactObj.type;addItem(item,1+Math.floor(Math.random()*2));interactObj.ready=false;toast(`+ ${item} · Recurso recolectado`);awardXP(5+maps[S.map].tier*2);save()}else if(dist(S,{x:1200,y:900})<110){openPanel('refugio')}else toast('No hay nada que recoger cerca')}
function die(){S.hp=0;S.dead=true;let items={};for(let k of Object.keys(S.inventory)){let lose=Math.floor(S.inventory[k]*.8);if(lose){items[k]=lose;S.inventory[k]-=lose}}let xpLost=Math.floor(S.xp*.2);S.xp-=xpLost;S.weapon=Math.max(0,S.weapon-1);S.armor=Math.max(0,S.armor-1);S.corpse={x:S.x,y:S.y,items,ready:true,r:22};$('#deathText').textContent=`Perdiste ${xpLost} XP y parte de tu equipo. El 80% de tus materiales está en tu mochila, en el lugar de tu caída.`;$('#deathScreen').classList.add('show');save()}
$('#respawnBtn').onclick=()=>{$('#deathScreen').classList.remove('show');S.dead=false;S.x=1200;S.y=900;S.hp=S.maxHp;S.stam=S.maxStam;S.map=0;makeWorld();toast('Puerto Ocaso · Recupera tu mochila');save()};

