// A winding shore path ties the procedural chunks together.
ctx.strokeStyle='rgba(227,207,157,.19)';ctx.lineWidth=40;ctx.beginPath();for(let x=-100;x<w+100;x+=30){let y=h*.73+Math.sin((x+cam.x)*.002)*42+Math.sin((x+cam.x)*.006)*12;if(x<0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke();
for(let d of decor){let x=d.x-cam.x,y=d.y-cam.y;if(x<-70||y<-70||x>w+70||y>h+70)continue;drawProp(x,y,d,p)}
for(let n of nodes){if(!n.ready)continue;let x=n.x-cam.x,y=n.y-cam.y;if(x<-40||y<-40||x>w+40||y>h+40)continue;ctx.fillStyle='#18221b99';ctx.beginPath();ctx.ellipse(x,y+8,n.r*1.1,7,0,0,Math.PI*2);ctx.fill();let col=({Madera:'#a97c4e',Cobre:'#d08c58',Hierbas:'#96bd68',Lino:'#d2ce9b',Roble:'#80624b',Setas:'#d27b6b',Pieles:'#bda57a',Mineral:'#a8a99a',Raíz:'#ab6c54',Polvo_arcano:'#b39ae0',Pescado:'#91bec0'})[n.type]||'#e3d19c';ctx.fillStyle=col;ctx.beginPath();ctx.arc(x,y,n.r*.48,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e7d8a777';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,n.r*.72,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#fff7d7';ctx.font='9px sans-serif';ctx.textAlign='center';ctx.fillText('✦',x,y+3)}
if(S.corpse){let x=S.corpse.x-cam.x,y=S.corpse.y-cam.y;ctx.fillStyle='#d5bc72';ctx.font='23px sans-serif';ctx.textAlign='center';ctx.fillText('♰',x,y);ctx.strokeStyle='#e4c978';ctx.beginPath();ctx.arc(x,y,27+Math.sin(S.day*4)*4,0,Math.PI*2);ctx.stroke()}
for(let e of enemies)drawEnemy(e,e.x-cam.x,e.y-cam.y);drawPlayer(S.x-cam.x,S.y-cam.y);for(let z of particles){z.x+=z.vx*.016;z.y+=z.vy*.016;z.life-=.016;ctx.globalAlpha=Math.max(0,z.life*2);ctx.fillStyle=z.color;ctx.fillRect(z.x-cam.x,z.y-cam.y,3,3)}particles=particles.filter(z=>z.life>0);ctx.globalAlpha=1;
let dark=Math.max(0,night-.48)*.35;ctx.fillStyle=`rgba(11,16,30,${dark})`;ctx.fillRect(0,0,w,h);if(S.map===2){let fog=ctx.createRadialGradient(w/2,h/2,80,w/2,h/2,Math.max(w,h)*.7);fog.addColorStop(0,'transparent');fog.addColorStop(1,'rgba(200,210,185,.16)');ctx.fillStyle=fog;ctx.fillRect(0,0,w,h)}if(S.map===14){ctx.fillStyle='rgba(92,30,58,.12)';ctx.fillRect(0,0,w,h)}
}
function drawProp(x,y,d,p){ctx.save();ctx.translate(x,y);ctx.fillStyle='#121b1699';ctx.beginPath();ctx.ellipse(3,d.r*.55,d.r*.9,d.r*.27,0,0,Math.PI*2);ctx.fill();if(d.t==='tree'){ctx.fillStyle='#57483b';ctx.fillRect(-4,0,8,d.r*.55);ctx.fillStyle=d.v>.5?p[3]:p[0];ctx.beginPath();ctx.arc(0,-d.r*.22,d.r*.65,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(-d.r*.4,-d.r*.05,d.r*.43,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(d.r*.38,-d.r*.05,d.r*.43,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff16';ctx.beginPath();ctx.arc(-d.r*.2,-d.r*.47,d.r*.26,0,Math.PI*2);ctx.fill()}else if(d.t==='grass'){ctx.strokeStyle=p[2];ctx.globalAlpha=.6;ctx.lineWidth=2;for(let j=0;j<4;j++){ctx.beginPath();ctx.moveTo(j*4-7,4);ctx.quadraticCurveTo(j*5-9,-d.r*.4,j*6-8,-d.r*.65);ctx.stroke()}}else{ctx.fillStyle=p[3];ctx.beginPath();ctx.ellipse(0,0,d.r*.56,d.r*.36,d.v,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff26';ctx.beginPath();ctx.ellipse(-3,-3,d.r*.2,d.r*.1,0,0,Math.PI*2);ctx.fill()}ctx.restore()}
