function openPanel(mode){$('#shade').classList.add('open');renderPanel(mode)}
function closePanel(){$('#shade').classList.remove('open')}
function renderPanel(mode,tab=''){
 const root=$('#panelContent');
 if(mode==='bag'){
  const active=tab||'items';
  root.innerHTML=`<span class="eyebrow">EQUIPO · MATERIALES · PROVISIONES</span><h2>Mochila del viajero</h2><p>Lo que cargas determina cuánto tiempo sobrevivirás lejos del refugio.</p><div class="tabs"><button data-tab="items" class="${active==='items'?'active':''}">Materiales</button><button data-tab="gear" class="${active==='gear'?'active':''}">Equipo</button><button data-tab="craft" class="${active==='craft'?'active':''}">Crafteo</button></div><div id="bagContent"></div>`;
  root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>renderPanel('bag',b.dataset.tab));
  const body=$('#bagContent');
  if(active==='items')body.innerHTML=`<div class="grid">${Object.entries(S.inventory).map(([k,v])=>`<div class="card"><span class="count">×${v}</span><b>${pretty(k)}</b><small>${resourceDescription(k)}</small></div>`).join('')}<div class="card"><span class="count">×${S.potions}</span><b>Poción de vida</b><small>Recupera 45 de salud.</small><button class="action-btn" data-use="potion">Beber</button></div><div class="card"><span class="count">×${Math.floor(S.food/10)}</span><b>Ración activa</b><small>Regeneración prolongada de salud.</small></div></div>`;
  if(active==='gear')body.innerHTML=`<div class="grid"><div class="card"><b>Arma</b><small>${S.weapon?'Espada de cobre · Ataque +8':'Arma improvisada · Daño base'}${S.rune?' · Encantada':''}</small></div><div class="card"><b>Armadura</b><small>${S.armor?'Cuero reforzado · +25 vida máxima':'Ropa de náufrago'}</small></div><div class="card"><b>Oro guardado</b><small>${S.bank.gold} monedas en el banco del refugio.</small></div><div class="card"><b>Profesiones</b><small>Recolección: botánica, tala, minería, pesca, caza y herboristería.<br>Crafteo: herrería, peletería, alquimia, cocina y encantamiento.</small></div></div>`;
  if(active==='craft')body.innerHTML=`<div class="grid">${recipes.map((r,i)=>`<div class="card"><div class="recipe"><div><b>${r.name}</b><small>${r.type} · ${r.effect}<br>Necesitas: ${Object.entries(r.need).map(([k,v])=>`${v} ${pretty(k)}`).join(' + ')}</small></div><button class="action-btn" data-craft="${i}">Crear</button></div></div>`).join('')}</div>`;
  body.querySelectorAll('[data-use="potion"]').forEach(b=>b.onclick=usePotion);
  body.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>craft(+b.dataset.craft));
 }else if(mode==='map'){
  root.innerHTML=`<span class="eyebrow">LAS TIERRAS DE LA NIEBLA CENICIENTA</span><h2>Atlas de la Frontera</h2><p>Quince regiones, cinco tiers. Cada frontera exige preparación y nivel suficiente.</p><div class="map-list">${maps.map((m,i)=>{let req=mapMinLevel(m),unlocked=S.level>=req;return `<button class="map-card ${unlocked?'':'locked'}" data-map="${i}"><span class="tier">${m.icon} TIER ${m.tier} · NIV. ${req}+</span><b>${m.name}</b><small>${m.hazard}</small>${i===S.map?'<small style="color:#ddc27c;margin-top:6px">● EXPLORANDO</small>':''}</button>`}).join('')}</div>`;
  root.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>travel(+b.dataset.map));
 }else if(mode==='refugio'){
  root.innerHTML=`<span class="eyebrow">PUERTO OCASO · ZONA SEGURA</span><h2>Refugio de frontera</h2><p>Repara el equipo antes de salir. Guarda monedas y prepara suministros; la frontera no perdona la improvisación.</p><div class="grid"><div class="card"><b>Reparación de equipo</b><small>La muerte daña tu equipo. Una reparación completa restaura su resistencia.</small><button class="action-btn" data-repair>Reparar · 12 ◈</button></div><div class="card"><b>Banco de Puerto Ocaso</b><small>En bolsillo: ${S.gold} ◈ · Guardado: ${S.bank.gold} ◈</small><button class="action-btn" data-bank="deposit">Guardar 10 ◈</button><button class="action-btn" data-bank="withdraw">Retirar 10 ◈</button></div><div class="card"><b>Preparación</b><small>Salud ${Math.ceil(S.hp)}/${S.maxHp} · Pociones ${S.potions} · Equipo ${S.weapon?'mejorado':'improvisado'}.</small><button class="action-btn" data-rest>Descansar · 5 ◈</button></div><div class="card"><b>Salir a explorar</b><small>Elige una región disponible en el atlas.</small><button class="action-btn" data-open-map>Consultar atlas</button></div></div>`;
  root.querySelector('[data-repair]').onclick=()=>{if(S.gold<12){toast('Necesitas 12 monedas');return}S.gold-=12;S.weapon=Math.max(1,S.weapon);S.armor=Math.max(1,S.armor);toast('Equipo reparado');save();renderPanel('refugio')};
  root.querySelectorAll('[data-bank]').forEach(b=>b.onclick=()=>{if(b.dataset.bank==='deposit'){if(S.gold<10)return toast('No tienes 10 monedas');S.gold-=10;S.bank.gold+=10}else{if(S.bank.gold<10)return toast('No hay monedas suficientes en el banco');S.bank.gold-=10;S.gold+=10}save();renderPanel('refugio')});
  root.querySelector('[data-rest]').onclick=()=>{if(S.gold<5)return toast('Necesitas 5 monedas');S.gold-=5;S.hp=S.maxHp;S.stam=S.maxStam;toast('Descansaste junto al fuego');save();renderPanel('refugio')};
  root.querySelector('[data-open-map]').onclick=()=>renderPanel('map');
 }else if(mode==='pause'){
  root.innerHTML=`<span class="eyebrow">PAUSA · PARTIDA GUARDADA AUTOMÁTICAMENTE</span><h2>Campamento de frontera</h2><p>La niebla espera. Respira, revisa el equipo y vuelve cuando estés listo.</p><div class="grid"><div class="card"><b>Progreso</b><small>Nivel ${S.level} · ${S.kills} enemigos vencidos · ${S.gold} monedas</small></div><div class="card"><b>Controles</b><small>WASD mover · Espacio atacar · Q/E habilidades · F recoger · Shift esquivar</small></div></div><button class="action-btn" data-resume style="margin-top:16px">Volver a la partida</button><button class="action-btn" data-save style="margin:16px 0 0 8px">Guardar progreso</button>`;
  root.querySelector('[data-resume]').onclick=closePanel;root.querySelector('[data-save]').onclick=()=>{save();toast('Progreso guardado')};
 }
}
function pretty(k){return k.replaceAll('_',' ')}
function resourceDescription(k){return ({Madera:'Leña, herramientas y construcción.',Cobre:'Metal base para armas y mejoras.',Hierbas:'Ingrediente para alquimia y cocina.',Lino:'Fibra para ropas y vendas.',Roble:'Madera dura de tierras interiores.',Setas:'Ingrediente medicinal y culinario.',Pieles:'Material para armadura ligera.',Mineral:'Mineral sin refinar.',Raíz:'Recurso de zonas pantanosas.',Polvo_arcano:'Catalizador para encantamientos.',Pescado:'Alimento costero.',})[k]||'Recurso de frontera.'}
function usePotion(){if(S.potions<1)return toast('No tienes pociones');if(S.hp>=S.maxHp)return toast('Tu salud ya está al máximo');S.potions--;S.hp=Math.min(S.maxHp,S.hp+45);toast('Poción usada · +45 salud');save();renderPanel('bag','items')}
function craft(i){let r=recipes[i];let lack=Object.entries(r.need).find(([k,n])=>(S.inventory[k]||0)<n);if(lack){toast(`Faltan ${pretty(lack[0])}`);return}for(let [k,n] of Object.entries(r.need))S.inventory[k]-=n;switch(r.gain){case'weapon':S.weapon++;break;case'armor':S.armor++;S.maxHp+=25;S.hp+=25;break;case'potion':S.potions++;break;case'food':S.food=90;S.hp=Math.min(S.maxHp,S.hp+20);break;case'rune':S.rune=true;break}toast(`${r.name} fabricado · ${r.effect}`);save();renderPanel('bag','craft')}
function travel(i){let m=maps[i],req=mapMinLevel(m);if(S.level<req){toast(`Necesitas nivel ${req} para cruzar esta frontera`);return}S.map=i;S.x=1200;S.y=900;makeWorld();closePanel();toast(`Explorando: ${m.name}`);save()}
function chooseClass(subclass){let options=subclass?[...new Set(classes.map(c=>c[1]))]:[...new Set(classes.map(c=>c[0]))];let chosen=subclass?S.primary:S.sub;let candidates=subclass?classes.filter(c=>c[0]===S.primary):classes;$('#shade').classList.add('open');let root=$('#panelContent');root.innerHTML=`<span class="eyebrow">${subclass?'NIVEL 30 · ESPECIALIZACIÓN':'NIVEL 15 · CAMINO DE CLASE'}</span><h2>${subclass?'Elige tu especialidad':'Define tu estilo de combate'}</h2><p>${subclass?'Tu disciplina secundaria completa una de las 16 clases híbridas.':'La clase primaria determina tu papel en la frontera.'} La elección queda guardada.</p><div class="grid">${(subclass?options:[...new Set(candidates.map(c=>c[0]))]).map((v)=>{let c=subclass?classes.find(c=>c[1]===v&&c[0]===S.primary):classes.find(c=>c[0]===v);return `<button class="map-card" data-class="${v}"><span class="tier">${subclass?S.primary:'CLASE PRIMARIA'}</span><b>${v}</b><small>Activas: ${c[2]} · ${c[3]}<br>Pasivas: ${c[4]} · ${c[5]}</small></button>`}).join('')}</div>`;
 root.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{if(subclass){S.sub=b.dataset.class;toast(`${S.primary} ${S.sub} · Híbrido desbloqueado`);closePanel()}else{S.primary=b.dataset.class;toast(`${S.primary} elegido · La especialidad se abre en nivel 30`);closePanel()}save()})
}

