$('#pauseBtn').onclick=()=>openPanel('pause');
$('#homeBtn').onclick=()=>openPanel('refugio');
$('#questBtn').onclick=()=>openPanel('map');
$('#closePanel').onclick=closePanel;
$('#shade').addEventListener('click',e=>{if(e.target===$('#shade'))closePanel()});
$('#attackBtn').onclick=attack;
$('#skill1').onclick=()=>useSkill(0);
$('#skill2').onclick=()=>useSkill(1);
$('#dodgeBtn').onclick=dodge;
$('#gatherBtn').onclick=interact;
addEventListener('keydown',e=>{
 const key=e.code;
 if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(key))e.preventDefault();
 if(e.repeat)return;
 keys[key]=true;
 if(key==='Space')attack();
 if(key==='KeyQ')useSkill(0);
 if(key==='KeyE')useSkill(1);
 if(key==='KeyF')interact();
 if(key==='ShiftLeft'||key==='ShiftRight')dodge();
 if(key==='Escape'){if($('#shade').classList.contains('open'))closePanel();else openPanel('pause')}
});
addEventListener('keyup',e=>{keys[e.code]=false});
const joystick=$('#joystick'),knob=$('#stickKnob');let joystickPointer=null;
function moveStick(e){const r=joystick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,d=Math.hypot(dx,dy),ratio=d>max?max/d:1;move.x=dx*ratio/max;move.y=dy*ratio/max;knob.style.transform=`translate(${dx*ratio}px,${dy*ratio}px)`}
joystick.addEventListener('pointerdown',e=>{e.preventDefault();joystickPointer=e.pointerId;joystick.setPointerCapture(e.pointerId);moveStick(e)});
joystick.addEventListener('pointermove',e=>{if(e.pointerId===joystickPointer)moveStick(e)});
function stopStick(e){if(e.pointerId!==joystickPointer)return;joystickPointer=null;move.x=0;move.y=0;knob.style.transform='translate(0,0)'}
joystick.addEventListener('pointerup',stopStick);joystick.addEventListener('pointercancel',stopStick);
updateHUD();
requestAnimationFrame(draw);
})();

