65:   if(active==='craft')body.innerHTML=`<div class="grid">${recipes.map((r,i)=>`<div class="card"><div class="recipe"><div><b>${r.name}</b><small>${r.type} · ${r.effect}<br>Necesitas: ${Object.entries(r.need).map(([k,v])=>`${v} ${pretty(k)}`).join(' + ')}</small></div><button class="action-btn" data-craft="${i}">Crear</button></div></div>`).join('')}</div>`;
