@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap');
:root{--ink:#f3ecdb;--muted:#b3b09e;--gold:#e4bd70;--gold2:#f0d99d;--panel:rgba(20,25,20,.94);--edge:rgba(233,210,157,.24);--red:#cf5d4c;--green:#97bd75}
*{box-sizing:border-box}
html,body{height:100%;margin:0;background:#111710;color:var(--ink);font-family:'DM Sans',sans-serif;overflow:hidden;touch-action:none}
button{font:inherit;color:inherit;cursor:pointer}
#game{position:relative;width:100%;height:100%;overflow:hidden;background:#354d3a;isolation:isolate}
#world{position:absolute;inset:0;width:100%;height:100%;display:block}
.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 46%,transparent 42%,rgba(5,9,7,.35) 100%),linear-gradient(180deg,rgba(8,12,10,.5),transparent 25%,transparent 60%,rgba(8,12,10,.35)}
.topbar{position:absolute;top:0;left:0;right:0;height:83px;padding:14px 28px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(12,17,14,.86),rgba(12,17,14,.28));border-bottom:1px solid rgba(255,255,255,.07)}
.brand{border:0;background:none;display:flex;align-items:center;gap:11px;text-align:left;padding:0}
.brand-mark{width:38px;height:38px;border:1px solid var(--gold);color:var(--gold);display:grid;place-items:center;transform:rotate(45deg);font-size:20px}
.brand b,.brand small{display:block;letter-spacing:.14em}
.brand b{font-size:12px;color:#f5e7c7}
.brand small{font-size:8px;color:#aaa894;margin-top:3px;letter-spacing:.18em}
.zone-title{position:absolute;left:50%;transform:translateX(-50%);text-align:center;min-width:260px}
.zone-title span,.zone-title b,.zone-title small{display:block}
.zone-title span{font-size:9px;letter-spacing:.2em;color:var(--gold);font-weight:700}
.zone-title b{font-family:'Playfair Display',serif;font-size:19px;font-weight:600;margin:2px 0}
.zone-title small{font-size:10px;color:#c5c1ad}
.top-actions{display:flex;gap:8px}
.icon-btn{width:38px;height:38px;background:rgba(16,23,18,.64);border:1px solid rgba(228,189,112,.3);border-radius:50%;font-size:19px;color:#e8d4a2}
.icon-btn:hover,.icon-btn:active{background:#d6b66d;color:#20251d}
.hero-hud{position:absolute;left:28px;top:101px;display:flex;align-items:center;gap:11px;width:263px;padding:10px 12px 10px 9px;background:linear-gradient(110deg,rgba(15,21,17,.88),rgba(15,21,17,.44));border:1px solid rgba(230,216,180,.14);border-radius:6px;backdrop-filter:blur(8px)}
.portrait{width:40px;height:45px;border:1px solid #c5a96c;background:linear-gradient(145deg,#665741,#252b24);display:grid;place-items:center;font-size:21px;color:#e5c779;position:relative}
.portrait i{position:absolute;width:8px;height:8px;background:#a7483d;border:1px solid #e8c986;border-radius:50%;right:-4px;top:-3px}
.vitals{flex:1;min-width:0}
.hero-line{display:flex;align-items:center;gap:6px;margin-bottom:6px}
.hero-line b{font-size:10px;letter-spacing:.1em}
.hero-line>span{font-size:8px;color:#c6c1ac}
.hero-line .gold{margin-left:auto;color:var(--gold);font-size:11px}
.hero-line .gold i{font-style:normal}
.bar{height:7px;background:rgba(0,0,0,.53);position:relative;margin:3px 0;border-radius:6px;overflow:hidden}
.bar i{display:block;height:100%;transition:width .22s;border-radius:6px}
.bar span{position:absolute;inset:0;text-align:center;font-size:7px;line-height:7px;text-shadow:0 1px 2px #000}
.hp i{background:linear-gradient(90deg,#9c332e,#e26350)}
.xp{height:4px}
.xp i{background:#dfbd70}
.xp span{display:none}
.stam{height:3px;width:76%;margin-top:5px}
.stam i{background:#92bd75}
.objective{position:absolute;top:103px;right:27px;max-width:320px;min-width:250px;display:flex;align-items:center;gap:10px;padding:10px 13px;background:rgba(13,20,16,.68);border-left:2px solid #d5b568;backdrop-filter:blur(7px)}
.quest-icon{font-size:18px;color:var(--gold)}
.objective div{min-width:0;flex:1}
.objective small,.objective b{display:block}
.objective small{font-size:8px;letter-spacing:.16em;color:#d9bd7a}
.objective b{font-weight:500;font-size:10px;margin-top:3px;color:#f1ead9}
.objective button{border:0;background:none;color:var(--gold);font-size:20px}
.toast{position:absolute;left:50%;top:20%;transform:translate(-50%,-10px);opacity:0;padding:10px 18px;background:rgba(16,22,17,.91);border:1px solid var(--edge);color:var(--gold2);font-size:12px;letter-spacing:.04em;transition:.25s;pointer-events:none;z-index:5}
.toast.show{opacity:1;transform:translate(-50%,0)}
.interact-hint{position:absolute;left:50%;bottom:21%;transform:translateX(-50%);opacity:0;padding:7px 12px;background:rgba(17,22,17,.86);border:1px solid var(--edge);border-radius:3px;color:var(--gold);font-size:13px;transition:.15s}
.interact-hint.show{opacity:1}
.interact-hint span{color:#eee7d7;font-size:11px;margin:0 8px}
kbd{font-size:9px;border:1px solid #777;padding:1px 5px;border-radius:2px;color:#ddd}
.combat-feed{position:absolute;right:28px;top:202px;text-align:right;font-size:11px;line-height:1.75;color:#f2d994;text-shadow:0 1px 4px #000;pointer-events:none}
.mobile-controls{display:none}
.desktop-help{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);font-size:9px;color:rgba(241,234,217,.6);letter-spacing:.04em;white-space:nowrap}
.desktop-help i{color:var(--gold);font-style:normal;margin:0 7px}
.panel-shade{position:absolute;inset:0;background:rgba(4,7,5,.66);backdrop-filter:blur(5px);display:none;align-items:center;justify-content:center;z-index:10;padding:18px}
.panel-shade.open{display:flex}
.panel{position:relative;width:min(670px,100%);max-height:min(82vh,720px);overflow:auto;background:linear-gradient(145deg,#202a21,#141b16 68%);border:1px solid rgba(228,189,112,.38);box-shadow:0 24px 80px #000b;padding:27px 30px 28px}
.panel:before{content:'';position:absolute;inset:6px;border:1px solid rgba(228,189,112,.1);pointer-events:none}
.close{position:absolute;right:18px;top:14px;border:0;background:none;font-size:25px;color:#c7b98f;z-index:1}
.panel h2{font:600 27px 'Playfair Display',serif;margin:3px 0;color:#f3e7cc}
.eyebrow{font-size:9px;letter-spacing:.2em;color:var(--gold);font-weight:700}
.panel p{font-size:12px;color:#b8b8a8;line-height:1.6}
.tabs{display:flex;gap:6px;margin:18px 0;border-bottom:1px solid #ffffff20}
.tabs button,.action-btn{border:1px solid #d9bd7738;background:#ffffff09;padding:8px 12px;font-size:10px;color:#e7dcbf}
.tabs button.active,.action-btn:hover{background:#b08c4b;color:#151a14}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:9px}
.card{padding:12px;background:#ffffff08;border:1px solid #ffffff15;min-height:75px}
.card b{display:block;font-size:12px;color:#eee4ca;margin-bottom:5px}
.card small{font-size:10px;line-height:1.45;color:#aaa995}
.card .count{float:right;color:var(--gold)}
.card button{display:block;margin-top:9px}
.map-list{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:16px}
.map-card{background:#ffffff08;border:1px solid #ffffff17;padding:12px;text-align:left;min-height:100px;color:var(--ink)}
.map-card b,.map-card small{display:block}
.map-card b{font:600 14px 'Playfair Display',serif;margin:6px 0}
.map-card small{font-size:9px;color:#b8b5a4;line-height:1.4}
.map-card .tier{font-size:8px;color:var(--gold);letter-spacing:.1em}
.map-card.locked{opacity:.42}
.recipe{display:flex;align-items:center;justify-content:space-between;gap:12px}
.recipe button{white-space:nowrap}
.level-flash{position:absolute;left:50%;top:40%;transform:translate(-50%,-50%) scale(.8);opacity:0;display:grid;justify-items:center;pointer-events:none;transition:.3s;text-shadow:0 3px 16px #000;z-index:7}
.level-flash.show{opacity:1;transform:translate(-50%,-50%) scale(1)}
.level-flash span{font-size:40px;color:var(--gold)}
.level-flash b{font:700 23px 'Playfair Display',serif;color:#f4d992;letter-spacing:.1em}
.level-flash small{font-size:12px;color:#fff4d8}
.death-screen{position:absolute;inset:0;display:none;place-items:center;background:radial-gradient(ellipse,rgba(68,22,22,.86),rgba(10,9,10,.96));z-index:15}
.death-screen.show{display:grid}
.death-card{text-align:center;width:min(410px,90%);padding:30px;border:1px solid rgba(204,112,89,.35);background:#160f10d9}
.death-mark{font-size:43px;color:#bd6255}
.death-card>small{display:block;margin-top:10px;color:#d78c75;font-size:9px;letter-spacing:.2em}
.death-card h2{font:600 30px 'Playfair Display',serif;margin:9px 0}
.death-card p{color:#bbb0a6;font-size:12px;line-height:1.6}
.death-card button{margin-top:12px;width:100%;padding:13px;background:#b89052;border:0;color:#211b13;font-size:10px;font-weight:700;letter-spacing:.12em}
.death-card button span{float:right}

